import { distanceM, type LngLat } from "./area.ts";
import { GENERATED_SPOTS } from "./generated/territory.ts";

/**
 * Pokémon Go's shape: plain **spots** (its PokéStops) everywhere, and a few
 * **event spots** (its gyms) where timed events and bosses happen.
 *
 * SPOTS below are hand-placed. The rest are generated by
 * tools/map/build_territory.py so a walker is never far from one: public
 * landmarks from the open data, a marker every 200 m along the trail, and
 * street corners filling any gap wider than ~140 m.
 *
 * A spot has no fixed type. What you find there is rolled per player and
 * refreshes every REFRESH_MIN: usually a fight, sometimes a rest, an elite, a
 * shop or a ? event. A spot can lean toward some finds (Krotona toward rest,
 * the Arcade toward shop).
 */
export type Find = "fight" | "elite" | "rest" | "shop" | "mystery";
export type SpotKind = "spot" | "event";

export interface Spot {
  id: string;
  /** Real-world name, for us. Players may see `gameName` instead. */
  name: string;
  /** In-game name when the real one can't be used (real businesses). */
  gameName?: string;
  kind: SpotKind;
  /** Where the spot sits: a public, legal place to stand. */
  at: LngLat;
  /** How close a player must be to play the spot, in metres. */
  radiusM: number;
  /** Multipliers on BASE_ODDS, e.g. { rest: 3 }. */
  leans?: Partial<Record<Find, number>>;
  note: string;
  /** Unchecked facts, to confirm on the ground before launch. */
  verify?: string;
}

/** Relative odds of each find at a plain spot. Tune with the lab. */
export const BASE_ODDS: Record<Find, number> = { fight: 60, rest: 12, elite: 10, shop: 8, mystery: 10 };

/** How often a spot rerolls what you find there, in minutes. */
export const REFRESH_MIN = 20;

