const GENERATED_NOTE: Record<string, string> = {
  trail: "A marker on the Ojai Valley Trail.",
  corner: "A street corner.",
};

export const SPOTS: Spot[] = [
  ...HAND_SPOTS,
  ...GENERATED_SPOTS.map((g): Spot => ({
    id: g.id,
    name: g.name,
    kind: "spot",
    at: g.at,
    radiusM: 35,
    note: GENERATED_NOTE[g.source] ?? `From the open map data (${g.source.replaceAll("_", " ")}).`,
    ...(g.verify ? { verify: g.verify } : {}),
  })),
];

export const spotById = (id: string) => SPOTS.find((s) => s.id === id);

/** Spots whose play radius the point is inside, nearest first. */
export function spotsInRange(p: LngLat): Spot[] {
  return SPOTS.map((s) => ({ s, d: distanceM(p, s.at) }))
    .filter(({ s, d }) => d <= s.radiusM)
    .sort((a, b) => a.d - b.d)
    .map(({ s }) => s);
}

/** The odds at one spot: BASE_ODDS times its leans, as fractions summing to 1. */
export function spotOdds(spot: Spot): Record<Find, number> {
  const raw = Object.fromEntries(
    (Object.keys(BASE_ODDS) as Find[]).map((f) => [f, BASE_ODDS[f] * (spot.leans?.[f] ?? 1)]),
  ) as Record<Find, number>;
  const total = Object.values(raw).reduce((a, b) => a + b, 0);
  for (const f of Object.keys(raw) as Find[]) raw[f] /= total;
  return raw;
}

/** FNV-1a → [0, 1). */
function hash01(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0) / 2 ** 32;
}

/**
 * What a player finds at a spot right now. Deterministic from (spot, player,
 * time slot), so the server can check it and the same player sees the same
 * thing until the slot turns over.
 */
export function findAt(spot: Spot, playerId: string, when: Date): Find {
  const slot = Math.floor(when.getTime() / (REFRESH_MIN * 6e4));
  let r = hash01(`${spot.id}|${playerId}|${slot}`);
  const odds = spotOdds(spot);
  for (const f of Object.keys(odds) as Find[]) {
    if ((r -= odds[f]) < 0) return f;
  }
  return "fight";
}
